<template x-teleport="body"><div x-show="open" x-cloak x-dialog="open" data-dialog-close="!busy && (open = false)" class="au-dialog-overlay am-member-modal" role="dialog" aria-modal="true" aria-labelledby="payment-modal-title" tabindex="-1"><section class="au-dialog bc-payment-dialog"><header class="au-dialog-heading"><div><h2 id="payment-modal-title" x-text="confirming ? @js(__('Cancel this payment?')) : @js(__('Transaction Details'))"></h2><p x-text="payment?.order_id || @js(__('Payment record'))"></p></div><button type="button" @click="open = false" :disabled="busy" class="au-dialog-close" aria-label="{{ __('Close dialog') }}"><i class="ph ph-x" aria-hidden="true"></i></button></header><div class="au-dialog-body">
    <p x-show="loading" class="bc-note bc-loading" role="status"><i class="ph ph-spinner ph-spin" aria-hidden="true"></i>{{ __('Loading transaction details…') }}</p><p x-show="error" x-text="error" class="bc-error" role="alert"></p>
    <template x-if="payment && !loading"><div>
        <div class="bc-payment-total"><div><span>{{ __('Recorded amount') }}</span><strong x-text="money(payment.amount)"></strong></div><span class="am-badge" :class="payment.status === 'SUCCESS' ? 'am-badge--success' : (['PENDING','WAITING'].includes(payment.status) ? 'am-badge--blue' : 'am-badge--danger')" x-text="statusLabel(payment.status)"></span></div>
        <dl class="am-facts am-facts-grid"><div><dt>{{ __('Member') }}</dt><dd><span x-text="user?.name || payment.customer_name || @js(__('Deleted member'))"></span><small x-text="user?.email || payment.customer_email || @js(__('No email on record'))"></small></dd></div><div><dt>{{ __('Environment') }}</dt><dd x-text="environment(payment.pakasir_is_sandbox)"></dd></div><div><dt>{{ __('Payment Channel') }}</dt><dd x-text="payment.payment_method || payment.payment_channel_code || @js(__('Not selected'))"></dd></div><div><dt>{{ __('Created At') }}</dt><dd x-text="date(payment.created_at)"></dd></div><div><dt>{{ __('Paid At') }}</dt><dd x-text="date(payment.paid_at)"></dd></div><div><dt>{{ __('Expires At') }}</dt><dd x-text="date(payment.expired_at || payment.va_expired_at)"></dd></div><div x-show="payment.pakasir_txn_id"><dt>{{ __('Pakasir transaction ID') }}</dt><dd x-text="payment.pakasir_txn_id"></dd></div><div x-show="payment.yukk_transaction_code"><dt>{{ __('YUKK transaction code') }}</dt><dd x-text="payment.yukk_transaction_code"></dd></div><div x-show="payment.va_number"><dt>{{ __('Virtual Account') }}</dt><dd x-text="payment.va_number"></dd></div></dl>
        <p class="bc-note bc-payment-notes" x-show="payment.notes" x-text="payment.notes"></p>
        <div x-show="confirming" class="bc-cancel-check"><p>{{ __('Request cancellation of this pending YUKK payment through the gateway. Review the latest payment status before continuing.') }}</p><div><button type="button" @click="confirming = false" :disabled="busy" class="au-button">{{ __('Keep payment') }}</button><button type="button" @click="cancel()" :disabled="busy" class="au-button au-button--danger"><span x-text="busy ? @js(__('Canceling…')) : @js(__('Confirm cancellation'))"></span></button></div></div>
        <div class="au-dialog-actions" x-show="!confirming"><a x-show="user" :href="user ? '/admin/users/' + user.id : '#'" class="au-button">{{ __('View member') }}</a><button type="button" @click="open = false" class="au-button">{{ __('Close') }}</button><button type="button" x-show="payment.can_cancel" @click="confirming = true" class="au-button au-button--danger">{{ __('Cancel payment') }}</button></div>
    </div></template>
</div></section></div></template>
